func expandUpsertAccountBalancesParams(dst *[]any, dialect runtime.Dialect, p paramsUpsertAccountBalances) error {
	_ = dialect
	_ = p
	if len(p.Items) == 0 {
		return runtime.ErrEmptySliceParam
	}
	if isAccountSettlementSorted(p.Items) {
		for i := range p.Items {
			*dst = append(*dst, p.Items[i].OrgID)
			*dst = append(*dst, p.Items[i].AccountID)
			*dst = append(*dst, p.Items[i].Currency)
			*dst = append(*dst, p.Items[i].DeltaCents)
		}
	} else {
		idxBuf := runtime.AcquireIndices(len(p.Items))
		idx := *idxBuf
		slices.SortFunc(idx, func(i, j int) int { return compareAccountSettlement(p.Items[i], p.Items[j]) })
		for _, k := range idx {
			*dst = append(*dst, p.Items[k].OrgID)
			*dst = append(*dst, p.Items[k].AccountID)
			*dst = append(*dst, p.Items[k].Currency)
			*dst = append(*dst, p.Items[k].DeltaCents)
		}
		runtime.ReleaseIndices(idxBuf)
	}
	return nil
}

